/* global __dirname */
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const source = fs.readFileSync(path.join(root, 'database/business-schema.ts'), 'utf8');
const match = /export const BUSINESS_SCHEMA = `([\s\S]*?)`;/m.exec(source);
if (!match || match[1].includes('${')) throw new Error('Expected a static BUSINESS_SCHEMA literal.');
fs.writeFileSync(path.join(root, 'docs/architecture/multirubro-reference.sql'),
  '-- Generated by npm run db:reference from database/business-schema.ts.\n' +
  '-- Reference of the additive v4 schema; restaurant baseline: database/schema.sql.\n' +
  '-- Runtime migration is owned by database/auth-database.ts. Do not import over a device backup.\n' +
  'PRAGMA foreign_keys = ON;\nBEGIN;\n' + match[1] + '\nCOMMIT;\n');
